$ErrorActionPreference = "Stop"

$ProjectRoot = (Get-Location).Path
$P03Path = Join-Path $ProjectRoot ".private\entity\build\P03\evidence-packets.json"
$CompilerPath = Join-Path $ProjectRoot "scripts\entity\build-cached-emet-explanations.js"
$PromptPath = Join-Path $ProjectRoot "scripts\entity\emet-prompts\emet-free-tier-v1.js"
$TestPath = Join-Path $ProjectRoot "scripts\entity\test-emet-reader-explanation.js"
$NotesPath = Join-Path $ProjectRoot "P04_BOUNDED_REPAIR_NOTES.md"
$SchedulerStatePath = Join-Path $ProjectRoot ".private\entity\build\P04\scheduler-state.json"
$GenerationStatePath = Join-Path $ProjectRoot ".private\entity\build\P04\generation-state.json"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot ".private\entity\backups\P04-bounded-reader-retry-v1.6.4-$Timestamp"

$CompilerPayload = ""
$PromptPayload = ""
$TestPayload = ""
$NotesPayload = ""

function Write-Payload([string]$Payload, [string]$Destination) {
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Destination) | Out-Null
    [System.IO.File]::WriteAllBytes($Destination, [Convert]::FromBase64String($Payload))
}

function Backup-File([string]$Path) {
    if (-not (Test-Path $Path)) { return }
    $relative = $Path.Substring($ProjectRoot.Length).TrimStart('\', '/')
    $destination = Join-Path $BackupRoot $relative
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) | Out-Null
    Copy-Item -Force $Path $destination
}

$Targets = @($CompilerPath, $PromptPath, $TestPath, $NotesPath, $SchedulerStatePath, $GenerationStatePath)
foreach ($target in $Targets) { Backup-File $target }

try {
    if (-not (Test-Path (Join-Path $ProjectRoot "package.json"))) {
        throw "Run this installer from the ai-bible-app project root."
    }
    if (-not (Test-Path $P03Path)) {
        throw "P03 evidence packets were not found at .private/entity/build/P03/evidence-packets.json."
    }

    Write-Host "Installing P04 bounded reader retry v1.6.4..." -ForegroundColor Cyan
    Write-Payload $CompilerPayload $CompilerPath
    Write-Payload $PromptPayload $PromptPath
    Write-Payload $TestPayload $TestPath
    Write-Payload $NotesPayload $NotesPath

    & node --check $CompilerPath
    if ($LASTEXITCODE -ne 0) { throw "Compiler syntax validation failed." }
    & node --check $PromptPath
    if ($LASTEXITCODE -ne 0) { throw "Prompt syntax validation failed." }
    & node --check $TestPath
    if ($LASTEXITCODE -ne 0) { throw "Reader test syntax validation failed." }

    $assertPath = Join-Path $ProjectRoot ".private\entity\assert-p04-v164.js"
    $assertCode = @'
const path = require("path");
const root = process.cwd();
const compiler = require(path.join(root, "scripts", "entity", "build-cached-emet-explanations.js"));
const prompt = compiler.promptDescriptor();
if (compiler.COMPILER_VERSION !== "1.6.4") throw new Error(`Unexpected compiler version ${compiler.COMPILER_VERSION}`);
if (prompt.version !== "1.4.4") throw new Error(`Unexpected prompt version ${prompt.version}`);
if (typeof compiler.callOpenAI !== "function") throw new Error("Bounded retry API was not exported.");
console.log(`Compiler              : ${compiler.COMPILER_VERSION}`);
console.log(`Prompt contract       : ${prompt.id}@${prompt.version}`);
console.log(`Reader test attempts  : 2 maximum`);
console.log("Invalid attempts saved: no");
'@
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $assertPath) | Out-Null
    [System.IO.File]::WriteAllText($assertPath, $assertCode, (New-Object System.Text.UTF8Encoding($false)))
    & node $assertPath
    if ($LASTEXITCODE -ne 0) { throw "v1.6.4 contract assertion failed." }
    Remove-Item -Force $assertPath

    if (Test-Path $GenerationStatePath) {
        $state = Get-Content $GenerationStatePath -Raw -Encoding UTF8 | ConvertFrom-Json
        if ($state.PSObject.Properties.Name -contains "failures") {
            $state.failures = [pscustomobject]@{}
        }
        $json = $state | ConvertTo-Json -Depth 100
        [System.IO.File]::WriteAllText((Resolve-Path $GenerationStatePath), $json + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
    }

    if (Test-Path $SchedulerStatePath) {
        $scheduler = Get-Content $SchedulerStatePath -Raw -Encoding UTF8 | ConvertFrom-Json
        $oldJob = $scheduler.activeJobId
        if (-not $scheduler.history) { $scheduler | Add-Member -NotePropertyName history -NotePropertyValue @() -Force }
        if ($oldJob) {
            $scheduler.history = @($scheduler.history) + [pscustomobject]@{
                at = (Get-Date).ToUniversalTime().ToString("o")
                action = "superseded-bounded-reader-retry"
                jobId = $oldJob
                newPromptVersion = "1.4.4"
            }
            Write-Warning "Local Batch job $oldJob belongs to the previous prompt and will not be imported."
        }
        $scheduler.activeJobId = $null
        if ($scheduler.PSObject.Properties.Name -contains "nextEligibleSubmitAt") { $scheduler.nextEligibleSubmitAt = $null }
        $json = $scheduler | ConvertTo-Json -Depth 100
        [System.IO.File]::WriteAllText((Resolve-Path $SchedulerStatePath), $json + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
    }

    Write-Host "`nP04 bounded reader retry v1.6.4 installed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupRoot"
    Write-Host "`nNext command:"
    Write-Host "npm run test:emet-reader -- --entity word:greek-nt:G0119" -ForegroundColor Yellow
    Write-Host "`nDo not restart emet:generate:watch until the repaired Greek NT test is approved."
}
catch {
    Write-Warning "Installation failed. Restoring previous files..."
    foreach ($target in $Targets) {
        $relative = $target.Substring($ProjectRoot.Length).TrimStart('\', '/')
        $backup = Join-Path $BackupRoot $relative
        if (Test-Path $backup) {
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
            Copy-Item -Force $backup $target
        }
    }
    throw
}
